export function normalizeJobMatchKey(job: {
  title: string;
  employer: string;
  location?: string;
}): string {
  const norm = (s?: string) =>
    (s || "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/(^-|-$)/g, "");
  return `${norm(job.title)}::${norm(job.employer)}::${norm(job.location)}`;
}

export function normalizeTitleEmployerKey(job: {
  title: string;
  employer: string;
}): string {
  const norm = (s?: string) =>
    (s || "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/(^-|-$)/g, "");
  return `${norm(job.title)}::${norm(job.employer)}`;
}

/**
 * Idempotently imports the 120 vacancy leads into an existing jobs collection without
 * deleting or overwriting pre-existing verified jobs or creating duplicates.
 */
export function mergeJobsIdempotently(
  existingJobs: JobListingRecord[],
  incomingLeads: JobListingRecord[] = ONE_TWENTY_VACANCY_LEADS
): { jobs: JobListingRecord[]; report: JobImportReport } {
  const existingCopy = existingJobs.map((j) => ({ ...j }));
  const byExactKey = new Map<string, number>();
  const byTitleEmployer = new Map<string, number>();
  const byId = new Map<string, number>();

  existingCopy.forEach((job, idx) => {
    byId.set(job.id, idx);
    byExactKey.set(job.sourceKey || normalizeJobMatchKey(job), idx);
    const teKey = normalizeTitleEmployerKey(job);
    if (!byTitleEmployer.has(teKey)) {
      byTitleEmployer.set(teKey, idx);
    }
  });

  let inserted = 0;
  let updated = 0;
  let skipped = 0;
  let duplicates = 0;

  const seenIncomingKeys = new Set<string>();
  const matchedExistingIndices = new Set<number>();
  const orderedLeadRecords: JobListingRecord[] = [];

  for (const incoming of incomingLeads) {
    const exactKey = incoming.sourceKey || normalizeJobMatchKey(incoming);
    const teKey = normalizeTitleEmployerKey(incoming);

    if (seenIncomingKeys.has(exactKey)) {
      duplicates += 1;
      skipped += 1;
      continue;
    }
    seenIncomingKeys.add(exactKey);

    let matchIdx = byId.get(incoming.id);
    if (matchIdx === undefined) {
      matchIdx = byExactKey.get(exactKey);
    }
    if (matchIdx === undefined) {
      matchIdx = byTitleEmployer.get(teKey);
    }

    if (matchIdx !== undefined) {
      matchedExistingIndices.add(matchIdx);
      const existing = existingCopy[matchIdx];

      // Check if existing job is already verified/active — never overwrite a verified job with a draft
      if (existing.status === "active" || existing.verificationStatus === "verified") {
        skipped += 1;
        orderedLeadRecords.push({
          ...existing,
          leadNumber: existing.leadNumber ?? incoming.leadNumber,
        });
        continue;
      }

      // Check if this exact lead was already imported previously (idempotent re-run)
      if (
        existing.id === incoming.id ||
        (existing.leadNumber === incoming.leadNumber &&
          existing.vacancyReference === incoming.vacancyReference)
      ) {
        duplicates += 1;
        skipped += 1;
        orderedLeadRecords.push(existing);
        continue;
      }

      // Otherwise enrich/update the unverified pre-existing record while preserving its ID & reference
      const mergedRecord: JobListingRecord = {
        ...existing,
        ...incoming,
        id: existing.id,
        slug: existing.slug || incoming.slug,
        jobReference: existing.jobReference || incoming.jobReference,
        leadNumber: incoming.leadNumber,
        auditLog: [
          ...(existing.auditLog || []),
          {
            timestamp: new Date().toISOString(),
            actor: "System Import",
            action: `Updated existing unverified listing with 120 Vacancy Leads draft (#${incoming.leadNumber})`,
          },
        ],
      };
      existingCopy[matchIdx] = mergedRecord;
      updated += 1;
      orderedLeadRecords.push(mergedRecord);
    } else {
      inserted += 1;
      orderedLeadRecords.push({ ...incoming });
    }
  }

  // Preserve all remaining pre-existing jobs that were not part of the 120 incoming leads
  const remainingExisting = existingCopy.filter(
    (_, idx) => !matchedExistingIndices.has(idx)
  );

  return {
    jobs: [...orderedLeadRecords, ...remainingExisting],
    report: {
      considered: incomingLeads.length,
      inserted,
      updated,
      skipped,
      duplicates,
      importedAt: new Date().toISOString(),
    },
  };
}
